 dict(slug='custom-boxes',name='Custom boxes',kind='paper',art=0,summary='Folding cartons, rigid gift boxes and corrugated mailers, sized around your product.',intro='Compare custom printed boxes by structure, protection and presentation. Start with product dimensions, quantity per design, artwork and delivery market to define a box specification for review.',formats=[('Folding cartons','Flat-supplied paperboard boxes for retail bottles, jars, tubes and compact products.'),('Rigid gift boxes','Lid-and-base, drawer and magnetic closure directions for presentation sets.'),('Mailer boxes','Corrugated packaging for ecommerce orders, subscription kits and product launches.'),('Shipping boxes','Transit packaging planned around packed weight, stacking and shipping conditions.'),('Packaging sleeves','Printed sleeves for product information and coordinated branding.'),('Box inserts','Paperboard and corrugated insert directions for product fit and removal.')]),
 dict(slug='paper-bags',name='Paper bags',kind='paper',art=1,summary='Kraft, retail and gift bags with your size, handle style and printed branding.',intro='Plan custom paper bags around product weight, bag dimensions and the carrying experience. Review paper, handles, base reinforcement, print coverage and finish together before confirming a specification.',formats=[('Kraft paper bags','A natural paper direction for retail and gifting applications.'),('Luxury shopping bags','Review paper weight, handle attachment and presentation finishes.'),('Paper gift bags','Coordinate bag dimensions, branded print and tissue for a gift range.'),('Twisted handle bags','Compare handle comfort, load requirements and bag proportions.'),('Flat handle bags','A practical carrying direction to review for retail projects.'),('Paper mailing bags','Review closure, tear resistance and parcel handling needs.')]),
 dict(slug='flexible-pouches',name='Flexible pouches',kind='flexible',art=2,summary='Stand-up, flat-bottom and spout formats for food, coffee, pet care and refills.',intro='Custom printed pouches combine a flexible material structure with the shape and features your product needs. Compare stand-up, flat-bottom, side-gusset and spout formats around fill weight, barrier needs and filling conditions.',formats=[('Stand-up pouches','A bottom-gusset format with optional zipper, window and hang-hole features.'),('Flat-bottom pouches','A structured shelf presentation for coffee, food and other dry products.'),('Side-gusset bags','Compare filled dimensions, closure and packing efficiency.'),('Spout pouches','Review liquid compatibility, filling route, spout and leak testing.'),('Three-side seal pouches','A flat format direction for compact or single-use products.'),('Printed rollstock','Review web width, unwind direction, sealing conditions and filling equipment.')]),
 dict(slug='plastic-bags',name='Plastic bags & mailers',kind='flexible',art=3,summary='Poly mailers, garment bags and resealable bags for retail and shipping.',intro='Explore custom plastic bags and printed poly mailers by application. Confirm film, thickness, opacity, closure, intended load and destination requirements before approving a production route.',formats=[('Poly mailers','Shipping bags with print and closure requirements matched to the parcel.'),('Garment bags','Review garment size, film clarity, ventilation and closure details.'),('Resealable plastic bags','Compare closure cycles, film and seal requirements.'),('Die cut handle bags','Review handle shape, load and reinforcement needs.'),('Plastic shopping bags','Material and permitted use require destination-market review.'),('Protective product bags','Review abrasion, puncture and packed-product compatibility.')]),
 dict(slug='cards-tags',name='Cards & hang tags',kind='print',art=4,summary='Insert cards, thank-you cards and hang tags that complete your brand story.',intro='Bring product information, care instructions and brand messaging into the pack with custom printed cards and hang tags. Specify finished size, paper, printed sides, artwork and any finishing or attachment requirements.',formats=[('Packaging insert cards','Communicate product information, care or a next step inside the package.'),('Thank-you cards','Coordinate a short brand message with the rest of the packaging.'),('Custom hang tags','Review hole position, attachment method and product display.'),('Product information cards','Plan readable text, diagrams and variant details.'),('Header cards','Match fold, attachment and retail display needs.'),('Care cards','Choose a layout that makes instructions easy to read.')]),
