def art(i):return f'<div class="art art-{i}"><img src="/assets/images/print-categories.webp" alt="{esc(CATEGORIES[i]["name"],quote=True)} with original fictional logos, slogans and printed graphics" width="1536" height="1024" loading="lazy"></div>'
def button(text,url,style=''):return f'<a class="button {style}" href="{esc(url,quote=True)}">{text}<span class="arrow" aria-hidden="true">↗</span></a>'
def qurl(product):
 from urllib.parse import quote
 return '/request-quote/?product='+quote(product)
def cards():
 return '<div class="productgrid">'+''.join(f'<a class="productcard" data-category="{c["kind"]}" href="/products/{c["slug"]}/">{art(c["art"])}<div class="cardtitle"><h3>{c["name"]}</h3><span class="arrow" aria-hidden="true">↗</span></div><p>{c["summary"]}</p></a>' for c in CATEGORIES)+'</div>'
def guides():return '<div class="resourcegrid">'+''.join(f'<article class="guidecard"><span class="eyebrow">{g[1]}</span><h3><a href="/guides/{g[0]}/">{g[2]}</a></h3><p>{g[3]}</p><a class="textlink" href="/guides/{g[0]}/">Read the guide ↗</a></article>' for g in GUIDES)+'</div>'
def faq():
 return '<div class="faq">'+''.join(f'<details><summary>{a}</summary><p>{b}</p></details>' for a,b in [
 ('Can I request several packaging products together?','Yes. Include the boxes, bags, cards and labels you are considering in one brief. List the quantity and artwork versions for each item so they can be reviewed separately.'),
 ('What is the minimum order quantity?','MOQ depends on the product, size, material, print route and quantity per design. Share your target quantity to request a project-specific minimum and suitable options.'),
 ('Can I start without final dimensions or artwork?','Yes. Describe the product, approximate size or fill weight and intended use. Add reference images when emailing the brief. Format, dimensions and artwork requirements can then be reviewed.'),
 ('How are samples and production timing confirmed?','Identify what the sample needs to verify and share your target delivery date. The sample route and production schedule need to be confirmed for the selected specification; transit time is considered separately.'),
 ('How do I discuss material or sustainability requirements?','State your destination market and intended use. Material, food-contact and environmental claims need documentation applicable to the actual structure. Paper-based or mono-material packaging should not be assumed recyclable in every market.')])+'</div>'
