def write(path,title,description,body,extra=None,lang='en',breadcrumb=None):
 file=OUT/path.strip('/')/'index.html' if path!='/' else OUT/'index.html';file.parent.mkdir(parents=True,exist_ok=True)
 schema=[{'@type':'WebSite','@id':ORIGIN+'/#website','name':'PackHubGlobe','url':ORIGIN+'/'},{'@type':'WebPage','@id':ORIGIN+path+'#webpage','name':title,'url':ORIGIN+path,'inLanguage':lang,'isPartOf':{'@id':ORIGIN+'/#website'}}]
 if path=='/':schema.append({'@type':'Organization','@id':ORIGIN+'/#brand','name':'PackHubGlobe','url':ORIGIN+'/','email':EMAIL})
 if path!='/':
  crumbs=[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'}]
  labels={'/products/':'Packaging','/guides/':'Guides','/industries/':'Industries',**{'/products/'+c['slug']+'/':c['name'] for c in CATEGORIES}}
  for i in range(1,len(path.strip('/').split('/'))+1):
   part='/'+('/'.join(path.strip('/').split('/')[:i]))+'/'
   label=labels.get(part,title.split(' | ')[0] if part==path else part.strip('/').split('/')[-1].replace('-',' ').title())
   crumbs.append({'@type':'ListItem','position':i+1,'name':label,'item':ORIGIN+part})
  schema.append({'@type':'BreadcrumbList','itemListElement':crumbs})
 if extra:schema.extend(extra)
 html='<!doctype html><html lang="'+lang+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><meta name="description" content="'+esc(description,quote=True)+'"><meta name="robots" content="index,follow"><link rel="canonical" href="'+ORIGIN+path+'"><meta property="og:title" content="'+esc(title,quote=True)+'"><meta property="og:description" content="'+esc(description,quote=True)+'"><meta property="og:type" content="website"><meta property="og:url" content="'+ORIGIN+path+'"><meta property="og:image" content="'+ORIGIN+'/assets/packaging-collection.webp"><meta name="theme-color" content="#214c3a"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/app.js" defer></script><script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@graph':schema},ensure_ascii=False).replace('</',r'<\/')+'</script></head><body>'+header(path)+'<main id="main">'+body+'</main>'+footer()+'</body></html>'
 file.write_text(html);PAGES[:]=[p for p in PAGES if p[0]!=path];PAGES.append((path,title,description))

