details=[('custom-boxes/mailer-boxes','Custom mailer boxes',0,'Corrugated mailer boxes for ecommerce, subscription kits and branded product delivery. Review internal dimensions, board, inserts and printed surfaces around the actual contents.',[('Dimensions','Internal length × width × depth; identify units and packing clearance.'),('Structure','Locking mailer format, closure and insert layout, subject to sample review.'),('Board direction','Kraft or white liner and board selection based on packed weight and transit needs.'),('Artwork','Printed sides, coverage, color reference, barcode and dieline version.'),('Validation','Product fit, closure, packing workflow and agreed transit tests.')]),('flexible-pouches/stand-up-pouches','Custom stand-up pouches',2,'Printed bottom-gusset pouches for food, coffee, pet products and other applications. Review format, film structure, closure and filling conditions together.',[('Dimensions','Width × height × bottom gusset; confirm the measuring convention and units.'),('Contents','Product type, fill weight, shelf-life target and storage conditions.'),('Material direction','Required barrier, film construction and sealing compatibility need project review.'),('Features','Zipper, valve, window, hang hole or tear notch as applicable to the structure.'),('Validation','Filled-product fit, seals, feature placement and applicable material documentation.')])]
