body=intro('Beauty & skincare packaging','A consistent brand.<br>From carton to carry bag.','Plan custom cosmetic packaging across folding cartons, gift boxes, fitted inserts, shopping bags and printed cards. Start with bottle and jar dimensions, sales channel and the quantity per variant.')+'<section class="wrap categorylead"><div>'+art(0)+'</div><div><h2>Protect the product.<br>Complete the presentation.</h2><p style="margin-top:24px">Daily retail, gift sets and ecommerce deliveries need different packaging decisions. Coordinate readable print and color references across every item in the range.</p><div class="actions" style="margin-top:25px">'+button('Plan my beauty packaging',qurl('Beauty & skincare'))+'</div></div></section><section class="section wrap"><h2>Build the packaging set.</h2><div class="formats" style="margin-top:25px">'+''.join(f'<article class="format"><h3>{a}</h3><p>{b}</p><a class="textlink" href="{url}">Compare options ↗</a></article>' for a,b,url in [('Retail cartons','Fit bottles and jars; check clearances and readable variant information.','/products/custom-boxes/'),('Gift presentation','Review insert retention, opening experience and decorative surfaces.','/products/custom-boxes/'),('Retail carry bags','Match bag proportions, load and handles to the complete purchase.','/products/paper-bags/'),('Insert & care cards','Connect product information and brand messaging.','/products/cards-tags/'),('Labels & seals','Check the actual substrate and application environment.','/products/stickers-labels/'),('Shipping protection','Plan a mailer around the finished retail pack.','/products/custom-boxes/mailer-boxes/')])+'</div></section>'+cta()
write('/industries/beauty-skincare/','Custom Cosmetic & Skincare Packaging | PackHubGlobe','Coordinate beauty cartons, gift boxes, paper bags, inserts and printed cards for your skincare brand.',body)

write('/guides/','Packaging Guides for B2B Buyers | PackHubGlobe','Prepare a packaging quote brief and compare box and pouch structures with practical buyer guides.',intro('The packaging notebook','Make the next<br>packaging decision clearer.','Practical starting guides for buyers, brand teams and sourcing managers. Use them to define the questions your sample and specification need to answer.')+'<section class="section wrap" style="padding-top:0">'+guides()+'</section>'+cta())
for slug,label,title,desc,sections in GUIDES:
 body=intro(label,title,desc,'<a href="/guides/">Guides</a> / '+label)+'<article class="article wrap">'
 body+=''.join(f'<h2>{a}</h2><p>{b}</p>' for a,b in sections)
 body+='<h2>Turn the decision into a brief.</h2><p>Share your product, quantity, dimensions or fill weight, artwork status and destination. <a href="/request-quote/">Prepare your packaging request</a> or <a href="/products/">compare packaging categories</a>.</p></article>'+cta()
 write('/guides/'+slug+'/',title+' | PackHubGlobe',desc,body)

body=intro('About PackHubGlobe','One packaging brief.<br>Connected manufacturing expertise.','PackHubGlobe brings together manufacturing expertise for paper packaging and flexible packaging projects. Enquiries are coordinated through one contact: '+EMAIL+'.')+'<section class="section wrap" style="padding-top:0"><div class="two"><article class="panel"><span class="eyebrow">Paper packaging</span><h3>Xiamen Finer Packaging Co., Ltd.</h3><p>Paper packaging manufacturing is represented by Xiamen Finer Packaging Co., Ltd. Its existing Finer Pack website focuses on cosmetic and skincare cartons, rigid boxes and mailers.</p><p><a href="https://www.finerpack.com/about" target="_blank" rel="noopener">Explore the existing Finer Pack company profile ↗</a></p></article><article class="panel"><span class="eyebrow">Flexible packaging</span><h3>Xiamen Unique Packaging Technology Co., Ltd.</h3><p>Flexible packaging is represented by Xiamen Unique Packaging Technology Co., Ltd. Its existing Unique Packaging website covers custom printed pouches and flexible packaging applications.</p><p><a href="https://uniquepouches.com/about.html" target="_blank" rel="noopener">Explore the existing Unique Packaging company profile ↗</a></p></article></div><div class="panel" style="margin-top:26px"><h3>A clear contact for the complete brief.</h3><p>All PackHubGlobe packaging enquiries go to <a href="mailto:'+EMAIL+'">'+EMAIL+'</a>. The quotation should identify the responsible supplying entity, approved specification, commercial terms and documentation for each product line.</p><p>Your quotation identifies the responsible supplying company and the specifications agreed for your order.</p><p><a href="/factory/">Review factory responsibilities and evidence requirements ↗</a></p></div></section>'+cta()
write('/about/','About PackHubGlobe | Paper & Flexible Packaging','Discover the paper and flexible packaging companies behind the PackHubGlobe brand and its shared enquiry contact.',body)
body=intro('Factory & capabilities','See the process.<br>Verify the details.','Manufacturing responsibilities and evidence should be clear before you approve a packaging order. This page maps the two supplying entities and the documents to review.')+'<section class="wrap section" style="padding-top:0">'+table([('Paper packaging','Xiamen Finer Packaging Co., Ltd. — refer to current company records and the Finer Pack manufacturing profile.'),('Flexible packaging','Xiamen Unique Packaging Technology Co., Ltd. — refer to current company records and the Unique Packaging factory profile.'),('Paper process review','Structure and dieline, artwork, material, printing, finishing, sample, inspection and export packing.'),('Flexible process review','Film structure, artwork, printing, lamination, pouch making, closures, seals and inspection.'),('Evidence to request','Current certificates with scope and expiry, relevant test reports, traceable samples, factory walkthrough and approved specification.'),('Additional product formats','For paper shopping bags, plastic retail bags, cards and labels, confirm the material, print route, quantity and final specification in your quotation.')])+'<div class="panel" style="margin-top:30px"><h3>Explore the production environment.</h3><p>Explore the <a href="https://www.finerpack.com/showroom">Finer Pack showroom</a> and <a href="https://uniquepouches.com/factory-tour.html">Unique Packaging factory tour</a> for manufacturing context. Ask for current samples, production references or a walkthrough relevant to your project.</p></div></section>'+cta()
write('/factory/','Factory & Packaging Capabilities | PackHubGlobe','Review paper and flexible packaging responsibilities, production steps and evidence requirements.',body)

body=intro('Start a project','Tell us about<br>your next packaging idea.','Share what you know. Product, quantity and destination give the brief a useful starting point. All enquiries are addressed to '+EMAIL+'.')+'<section class="wrap section quotegrid" style="padding-top:0"><div class="panel"><span class="preview-pill">Send your brief by email</span><form id="quote-form"><div class="formgrid">'
fields=[('name','Your name *','text',True),('email','Business email *','email',True),('company','Company / brand','text',False),('country','Delivery country / region *','text',True)]
for name,label,type_,required in fields:body+=f'<div class="field"><label for="{name}">{label}</label><input id="{name}" name="{name}" type="{type_}" '+('required ' if required else '')+f'autocomplete="'+{'name':'name','email':'email','company':'organization','country':'country-name'}[name]+'" maxlength="180"></div>'
body+='<div class="field"><label for="product">Packaging type *</label><select id="product" name="product" required><option value="">Select a starting point</option>'+''.join(f'<option>{c["name"]}</option>' for c in CATEGORIES)+'<option>Multiple packaging products</option><option>Not sure yet</option></select></div><div class="field"><label for="quantity">Target quantity per design *</label><input id="quantity" name="quantity" required maxlength="180" placeholder="e.g. 5,000 per design, 2 designs"></div><div class="field"><label for="size">Size or fill weight</label><input id="size" name="size" maxlength="180" placeholder="Approximate is fine"></div><div class="field"><label for="unit">Dimension unit</label><select id="unit" name="unit"><option>mm</option><option>cm</option><option>inches</option><option>Not decided</option></select></div><div class="field full"><label for="timing">Target delivery window</label><input id="timing" name="timing" maxlength="180" placeholder="Your launch date or preferred arrival window"></div><div class="field full"><label for="details">Product, artwork & packaging needs</label><textarea id="details" name="details" rows="5" maxlength="5000" placeholder="What are you packing? Include materials, features, print, artwork status and other items in the range."></textarea><small>Attach artwork or reference files in your email client after opening the draft.</small></div></div><label class="check"><input name="consent" type="checkbox" required><span>I understand this form prepares a brief for my email client. Nothing is sent until I send the email. <a class="textlink" href="/privacy/">Privacy information</a></span></label><div class="actions"><button class="button" type="submit">Prepare email brief <span class="arrow" aria-hidden="true">↗</span></button><button class="button light" type="button" id="download-brief">Download brief</button></div><div id="form-result" class="status" role="status" hidden><strong>Your brief is ready. It has not been sent.</strong><p>Open the draft below and send it from your email client. If no mail application is configured, download the brief and email it to '+EMAIL+'.</p><a class="textlink" id="email-draft" href="mailto:'+EMAIL+'">Open email draft →</a></div></form></div><aside class="quoteaside"><span class="eyebrow">ONE CONTACT FOR YOUR PROJECT</span><h3>Start with what<br>you already know.</h3><p style="margin-top:20px">You don’t need a finished specification to begin.</p><ul><li>The product and its approximate size or fill weight</li><li>Quantity per design and number of variants</li><li>Preferred packaging format or a reference</li><li>Delivery market and timing</li></ul><a class="email" href="mailto:'+EMAIL+'">'+EMAIL+'</a><p style="margin-top:25px">MOQ, sampling, production and freight will need project-specific confirmation.</p></aside></section>'
write('/request-quote/','Request a Custom Packaging Quote | PackHubGlobe','Prepare a brief for boxes, bags, pouches, cards and labels. Contact '+EMAIL+' with your product, quantity and destination.',body)
write('/privacy/','Privacy Information — Design Preview | PackHubGlobe','Understand how this frontend preview handles your packaging enquiry details.',intro('Privacy','Your brief stays in your browser.','This design preview does not include a form-submission server or analytics tracking.')+'<article class="article wrap"><h2>What happens to form information?</h2><p>The form prepares an email link or a text file locally in your browser. Clicking the email-draft link passes the entered brief to your selected email application, addressed to '+EMAIL+'. It does not send the email automatically. The download creates a local copy of the same brief.</p><h2>External resources</h2><p>The preview loads fonts from Google Fonts. External company-reference links are shown only on the About and Factory pages. No visitor analytics or marketing cookies are intentionally installed in this prototype.</p><h2>Before a public launch</h2><p>A complete public privacy notice must identify the responsible controller, enquiry processing, service providers, retention, international transfers and relevant rights. That notice and a secure server delivery endpoint are launch requirements.</p></article>')

